-- lebo-business-consulting-annlin (researched)
UPDATE businesses SET description = 'Lebo Business Consulting is a 100% Black woman-owned consultancy founded in 2006, offering strategic business planning, operational efficiency assessments, market analysis and business transformation and change-management support to clients it describes as carefully chosen rather than taken on in bulk, deliberately keeping its client list small enough to give each one direct attention.

The consultancy is SETA accredited across several training areas and also works on executive search, contingency recruitment, permanent placements and flexible staffing solutions, pairing its strategy work with practical human resources and recruitment services such as advertising, response handling and shortlisting for open roles. Based in Annlin, Pretoria, it suits businesses wanting both strategic consulting and the recruitment or HR support to carry a change through.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://leboconsulting.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'lebo-business-consulting-annlin' AND description = 'Lebo Business Consulting is a business consultancy in Annlin, 100% black-woman-owned and established in 2006, offering strategic business planning, operational efficiency assessments, market analysis and business transformation and change-management support, and is SETA accredited across several training areas.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- lefatshe-minerals-and-consulting-pty-ltd-klerksoord (researched)
UPDATE businesses SET description = 'Lefatshe Minerals and Consulting is a 100% Black-owned company, with 80% female and 20% male ownership, established in 2015 and focused on strategic water studies, geotechnical and geological services, environmental services, and civil design and construction.

Since its establishment, the company has completed water, minerals-exploration, geophysical survey and geotechnical projects both within South Africa and internationally, drawing on a multi-disciplinary team of professionals across its service areas, and works with selected partners on larger projects to deliver an end-to-end service. Based in Klerksoord, Akasia, it serves clients needing technical water, geological or environmental studies ahead of construction or mineral development.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://lefatsheminerals.co.za/about-us'), description_enriched_at = datetime('now') WHERE slug = 'lefatshe-minerals-and-consulting-pty-ltd-klerksoord' AND description = 'Lefatshe Minerals and Consulting, established in 2015, is a black-owned company focused on strategic water studies, geotechnical and geological services, environmental services, and civil design and construction, having completed water, minerals-exploration and geotechnical projects both locally and internationally.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
